} LIMIT 200

SELECT ?z ?lab WHERE {
  ?z a brick:HVAC_Zone .
  OPTIONAL {?z rdfs:label ?lab}
} LIMIT 200

SELECT ?zlab ?sensor ?point ?tsid WHERE {
  ?z a brick:HVAC_Zone ; rdfs:label ?zlab .
  ?sensor brick:hasLocation ?z ; a brick:Zone_Air_Temperature_Sensor .
